2	//!
3	//! The loop lives here — once, for every model line — so its conventions
4	//! (drain order, one metrics publish and one commit per iteration, shutdown
5	//! and fatal handling) are code, not per-crate discipline. A model line's
6	//! runtime obligation is exactly the three [`Scheduler`] methods. Anything
7	//! beyond them (e.g. LoRA control) is not the contract's business: a
8	//! scheduler that serves an extra capability captures its own channel before
9	//! spawn and drains it inside `step`.
10	
11	use super::ledger::RequestLedger;
12	use super::metrics::SchedulerMetrics;
13	use super::step::QueuedRequest;
14	use super::wiring::LiveScheduler;
15	use super::wiring::SchedulerBackend;
16	use super::wiring::scheduler_pair;
17	
18	/// One scheduler's runtime behavior. Runs on a dedicated OS thread spawned
19	/// by [`spawn_scheduler`]; `Send` suffices.
20	pub trait Scheduler: Send {
21	    /// Take ownership of one submitted request. Ownership transfer only —
22	    /// every verdict (admit/reject/retire) is written to the ledger from
23	    /// [`Self::step`], the single emission site. Nothing is lost by
24	    /// deferring: the driver commits once per iteration, so a verdict
25	    /// recorded in `step` lands in the same commit a submit-time verdict
26	    /// would have.
27	    fn submit(&mut self, request: QueuedRequest);
28	
29	    /// Advance one step: admission, GPU work, and per-request ledger writes.
30	    /// The driver loops over this without pause — an idle scheduler returns
31	    /// quickly and gets polled again, so in-flight completions from the
32	    /// scheduler's own worker threads are picked up within a step. Recoverable
33	    /// execution failures are the scheduler's to absorb (fail the touched
34	    /// requests, keep serving); `Err` means the engine is beyond use. The
35	    /// driver then writes off every open account with the error and winds
36	    /// down.
37	    fn step(&mut self, ledger: &mut RequestLedger) -> anyhow::Result<()>;
38	
39	    /// Metrics snapshot; the driver publishes it once per iteration.
40	    fn metrics(&self) -> SchedulerMetrics;
41	}
42	
43	/// Spawn one scheduler: mint the wiring, start the driver thread, return the
44	/// frontend end. `name` names the OS thread (shows in `top`/gdb).
45	pub fn spawn_scheduler<S: Scheduler + 'static>(name: &str, scheduler: S) -> LiveScheduler {
46	    let (handle, backend) = scheduler_pair();
47	    let join = std::thread::Builder::new()
48	        .name(name.to_string())
49	        .spawn(move || drive(scheduler, backend))
50	        .expect("failed to spawn scheduler thread");
51	    LiveScheduler { handle, join }
52	}
53	
54	/// The polling loop. Exits when the frontend is gone (submission channel
55	/// disconnected) and the scheduler reports itself drained, or when `step`
56	/// reports a fatal error. An idle iteration (nothing running or waiting) ends
57	/// in a [`std::hint::spin_loop`] before the next probe; busy iterations never
58	/// pause.
59	pub fn drive<S: Scheduler>(mut scheduler: S, backend: SchedulerBackend) {
60	    let SchedulerBackend {
61	        submissions,
62	        mut ledger,
63	        metrics,
64	    } = backend;
65	    let mut submissions_open = true;
66	    loop {
67	        loop {
68	            match submissions.try_recv() {
69	                Ok(envelope) => {
70	                    let queued = ledger.register(envelope);
71	                    scheduler.submit(queued);
72	                }
73	                Err(crossbeam_channel::TryRecvError::Empty) => break,
74	                Err(crossbeam_channel::TryRecvError::Disconnected) => {
75	                    submissions_open = false;
76	                    break;
77	                }
78	            }
79	        }
80	        let step = scheduler.step(&mut ledger);
81	        let snapshot = scheduler.metrics();
82	        metrics.publish(&snapshot);
83	        ledger.commit_step();
84	        if let Err(error) = step {
85	            // The ledger holds an account for every unanswered request, so
86	            // the write-off reaches them all — including any the scheduler
87	            // lost track of — with the real error attached.
88	            log::error!("scheduler fatal, engine winding down: {error:#}");
89	            ledger.fail_all(&format!("engine fatal: {error:#}"));
90	            ledger.commit_step();
91	            return;
92	        }
93	        if snapshot.num_running_reqs == 0 && snapshot.num_waiting_reqs == 0 {
94	            if !submissions_open {
95	                log::info!("scheduler drained after frontend shutdown, exiting");
96	                return;
97	            }
98	            // The iteration did no work; relax the core's issue slots before
99	            // probing again. Latency is untouched — busy iterations never
100	            // reach this hint.
101	            std::hint::spin_loop();
102	        }
103	    }
104	}
