1	//! Wiring between one frontend and one scheduler, plus the engine bundle a
2	//! model line hands back from `launch`.
3	//!
4	//! Both ends of a scheduler are minted together by [`scheduler_pair`], so a
5	//! model crate cannot cross-wire or forget a line: the scheduler side arrives
6	//! as one [`SchedulerBackend`] value, the frontend side as one
7	//! [`SchedulerHandle`]. Channel choices per direction: the submit channel is
8	//! crossbeam (sync consumer on the scheduler thread; senders never block on
9	//! unbounded channels), the step stream is tokio (async consumer in the
10	//! protocol stack; the sync producer's send never blocks either), metrics are
11	//! a shared cell (read-only pull, deliberately unsubscribable — see
12	//! [`MetricsPublisher`]).
13	//!
14	//! How many schedulers an engine runs and what each one means (DP replicas,
15	//! anything else) is the model line's decision; the contract carries the
16	//! collection and attaches no rank semantics to it. Placement across
17	//! schedulers is frontend policy.
18	
19	use std::sync::Arc;
20	use std::sync::Mutex;
21	use std::sync::atomic::AtomicBool;
22	use std::sync::atomic::AtomicU64;
23	use std::sync::atomic::Ordering;
24	use std::time::Instant;
25	
26	use super::control::LoraClient;
27	use super::kv::KvCapacity;
28	use super::ledger::RequestLedger;
29	use super::metrics::SchedulerMetrics;
30	use super::request_lifecycle::RequestControl;
31	use super::request_lifecycle::RequestEnvelope;
32	use super::request_lifecycle::StepReceiver;
33	use super::step::Request;
34	use super::step::RequestId;
35	
36	/// Everything the scheduler thread consumes and produces. The driver
37	/// ([`super::drive`]) destructures this; model code only ever sees the
38	/// ledger, through the `step` argument.
39	pub struct SchedulerBackend {
40	    pub(crate) submissions: crossbeam_channel::Receiver<RequestEnvelope>,
41	    pub(crate) ledger: RequestLedger,
42	    pub(crate) metrics: MetricsPublisher,
43	}
44	
45	/// Sole writer of a scheduler's metrics cell; the driver publishes once per
46	/// iteration from [`super::Scheduler::metrics`].
47	///
48	/// Deliberately a plain cell and not a `watch` channel: the driver busy-polls,
49	/// so a subscription edge (`changed()`) would fire per spin and turn any
50	/// subscriber into a message flood at idle. With only
51	/// [`SchedulerHandle::metrics`] to read it, "notify me on metrics change" is
52	/// unrepresentable — consumers pull the snapshot at the moment they need one.
53	/// A `Mutex` (not per-field atomics) so a reader never sees fields torn
54	/// across two steps; both sides touch it uncontended for nanoseconds.
55	pub struct MetricsPublisher(Arc<Mutex<SchedulerMetrics>>);
56	
57	impl MetricsPublisher {
58	    pub(crate) fn publish(&self, snapshot: &SchedulerMetrics) {
59	        *self.0.lock().expect("metrics cell poisoned") = *snapshot;
60	    }
61	}
62	
63	/// The frontend's end of one running scheduler.
64	pub struct SchedulerHandle {
65	    submit_tx: crossbeam_channel::Sender<RequestEnvelope>,
66	    steps: Option<StepReceiver>,
67	    metrics: Arc<Mutex<SchedulerMetrics>>,
68	    next_id: AtomicU64,
69	    /// Kept so requests minted after the scheduler thread exits still get
70	    /// their drop-bomb terminal delivered (the envelope needs a live sender).
71	    step_tx: super::request_lifecycle::StepSender,
72	}
73	
74	impl SchedulerHandle {
75	    /// Mint identity, queue timestamp, and abort flag, then hand the request
76	    /// to the scheduler. Never fails: if the scheduler is gone, the
77	    /// [`RequestEnvelope`]'s drop bomb answers the request with a
78	    /// `Failed` terminal on the step stream, which the caller observes like
79	    /// any other terminal.
80	    pub fn submit(&self, request: Request) -> RequestControl {
81	        let id = RequestId::new(self.next_id.fetch_add(1, Ordering::Relaxed));
82	        let abort = Arc::new(AtomicBool::new(false));
83	        let control = RequestControl::new(id, Arc::clone(&abort));
84	        let envelope =
85	            RequestEnvelope::new(id, abort, self.step_tx.clone(), request, Instant::now());
86	        if let Err(returned) = self.submit_tx.send(envelope) {
87	            drop(returned.into_inner());
88	        }
89	        control
90	    }
91	
92	    /// The step stream, handed out once (there is one stream and one
93	    /// consumer — the protocol stack's translation loop).
94	    pub fn take_steps(&mut self) -> Option<StepReceiver> {
95	        self.steps.take()
96	    }
97	
98	    /// The scheduler's most recent metrics snapshot. Pull-only by design (see
99	    /// [`MetricsPublisher`]): read it at the moment you need one — routing a
100	    /// request, stamping stats onto an outgoing batch, serving a scrape.
101	    pub fn metrics(&self) -> SchedulerMetrics {
102	        *self.metrics.lock().expect("metrics cell poisoned")
103	    }
104	}
105	
106	/// Mint both ends of one scheduler's wiring.
107	#[must_use]
108	pub fn scheduler_pair() -> (SchedulerHandle, SchedulerBackend) {
109	    let (submit_tx, submit_rx) = crossbeam_channel::unbounded();
110	    let (step_tx, step_rx) = tokio::sync::mpsc::unbounded_channel();
111	    let metrics = Arc::new(Mutex::new(SchedulerMetrics::default()));
112	    (
113	        SchedulerHandle {
114	            submit_tx,
115	            steps: Some(step_rx),
116	            metrics: Arc::clone(&metrics),
117	            next_id: AtomicU64::new(0),
118	            step_tx: step_tx.clone(),
119	        },
120	        SchedulerBackend {
121	            submissions: submit_rx,
122	            ledger: RequestLedger::new(step_tx),
123	            metrics: MetricsPublisher(metrics),
124	        },
125	    )
126	}
127	
128	/// What `ModelLine::launch` returns for a step-driven engine — a handoff
129	/// package the protocol stack dissolves at wiring time. Required fields are
130	/// the onboarding checklist: an engine that reports no capacity or no
131	/// servable length says so explicitly with `None`, it cannot just forget.
132	pub struct Engine {
133	    /// The engine's running schedulers, one handle each. How many and what
134	    /// they mean is the model line's business.
135	    pub schedulers: Vec<LiveScheduler>,
136	    pub info: EngineInfo,
137	    /// LoRA adapter control, for engines that serve it. The `Option` is the
138	    /// capability — no separate flag exists to disagree with it.
139	    pub lora: Option<LoraClient>,
140	}
141	
142	pub struct LiveScheduler {
143	    pub handle: SchedulerHandle,
144	    /// The driver thread. Joined by the server at shutdown, after the handles
145	    /// (and with them the submit senders) are dropped.
146	    pub join: std::thread::JoinHandle<()>,
147	}
