1	//! The vLLM EngineCore bridge for step-driven engines.
2	//!
3	//! Where the legacy bridge re-folds a per-token event stream into burst
4	//! outputs, this one translates each [`StepOutputs`] message 1:1 into one
5	//! `EngineCoreOutputs`: the scheduler already batched the step, and each
6	//! [`RequestUpdate`] is already the per-request fold. Wall-clock timestamps
7	//! for the wire are rendered from the contract's monotonic `Instant`s against
8	//! a per-bridge anchor.
9	
10	use std::collections::BTreeSet;
11	use std::collections::HashMap;
12	use std::sync::Arc;
13	use std::time::Instant;
14	
15	use anyhow::Context;
16	use anyhow::Result;
17	use anyhow::bail;
18	use fastrace::Span;
19	use fastrace::collector::SpanContext;
20	use log::info;
21	use log::warn;
22	use tokio_util::sync::CancellationToken;
23	use vllm_engine_core_client::protocol::logprobs::Logprobs;
24	use vllm_engine_core_client::protocol::logprobs::MaybeWireLogprobs;
25	use vllm_engine_core_client::protocol::logprobs::PositionLogprobs;
26	use vllm_engine_core_client::protocol::output::EngineCoreEvent;
27	use vllm_engine_core_client::protocol::output::EngineCoreEventType;
28	use vllm_engine_core_client::protocol::output::EngineCoreFinishReason;
29	use vllm_engine_core_client::protocol::output::EngineCoreOutput;
30	use vllm_engine_core_client::protocol::output::RequestBatchOutputs;
31	use vllm_engine_core_client::protocol::output::StopReason;
32	use vllm_engine_core_client::protocol::request::EngineCoreRequest;
33	use vllm_engine_core_client::protocol::request::EngineCoreRequestType;
34	use vllm_engine_core_client::protocol::stats::PrefillStats;
35	use vllm_engine_core_client::protocol::stats::SchedulerStats;
36	use vllm_engine_core_client::protocol::utility::UtilityCallId;
37	use zeromq::ZmqMessage;
38	use zeromq::prelude::SocketRecv;
39	
40	use super::BridgeLink;
41	use super::SpecDecodeTracker;
42	use super::connect_link;
43	use super::engine_output;
44	use super::now_secs_f64;
45	use super::scheduler_stats_from;
46	use super::send_outputs;
47	use super::send_terminal_output;
48	use super::send_utility_response;
49	use super::stop_sentinel_id;
50	use crate::engine::FinishReason;
51	use crate::engine::KvCapacity;
52	use crate::engine::Request;
53	use crate::engine::RequestControl;
54	use crate::engine::RequestId;
55	use crate::engine::RequestUpdate;
56	use crate::engine::SchedulerHandle;
57	use crate::engine::StepOutputs;
58	use crate::engine::Terminal;
59	use crate::vllm::wire::convert_finish_reason;
60	use crate::vllm::wire::convert_sampling;
61	use crate::vllm::wire::lora_adapter_from_sampling_params;
62	use crate::vllm::wire::requested_logprobs;
63	use crate::vllm::wire::requested_prompt_logprobs;
64	use crate::vllm::wire::to_wire_position_logprobs;
65	use crate::vllm::wire::to_wire_prompt_logprobs;
66	
67	pub(crate) struct SteppedEngineBridge {
68	    pub(crate) input_address: String,
69	    pub(crate) output_address: String,
70	    pub(crate) scheduler: SchedulerHandle,
71	    pub(crate) kv_capacity: Option<KvCapacity>,
72	    pub(crate) max_model_len: u32,
73	    pub(crate) engine_index: u32,
74	    pub(crate) data_parallel_size: u32,
75	}
76	
77	impl SteppedEngineBridge {
78	    pub(crate) async fn run(mut self, shutdown: CancellationToken) -> Result<()> {
79	        let mut steps = self
80	            .scheduler
81	            .take_steps()
82	            .context("partition step stream already taken")?;
83	        let mut spec = SpecDecodeTracker::default();
84	        // Stats are pull-at-send: no push task, the load cell is read when a
85	        // batch goes out (and once here, so the frontend's gauges initialize
86	        // before any traffic). An idle engine publishes nothing.
87	        let BridgeLink {
88	            mut input,
89	            output_tx,
90	            mut child_tasks,
91	        } = connect_link(
92	            &self.input_address,
93	            &self.output_address,
94	            self.engine_index,
95	            self.data_parallel_size,
96	            self.max_model_len,
97	            self.kv_capacity,
98	            None,
99	            &shutdown,
100	        )
101	        .await?;
102	        send_outputs(
103	            &output_tx,
104	            RequestBatchOutputs {
105	                engine_index: self.engine_index,
106	                scheduler_stats: Some(Box::new(self.stats(&mut spec))),
107	                timestamp: now_secs_f64(),
108	                ..Default::default()
109	            }
110	            .into(),
111	        )?;
112	
113	        let anchor = UnixAnchor::now();
114	        let mut streams: HashMap<RequestId, SteppedStream> = HashMap::new();
115	        let mut names: HashMap<String, RequestId> = HashMap::new();
116	
117	        info!(
118	            "local vLLM engine {} stepped bridge connected: input={}, output={}, max_model_len={}",
119	            self.engine_index, self.input_address, self.output_address, self.max_model_len
120	        );
121	
122	        let run_result = loop {
123	            tokio::select! {
124	                biased;
125	                () = shutdown.cancelled() => break Ok(()),
126	                joined = child_tasks.join_next(), if !child_tasks.is_empty() => {
127	                    if shutdown.is_cancelled() {
128	                        break Ok(());
129	                    }
130	                    break match joined {
131	                        Some(Ok((name, Ok(())))) => {
132	                            Err(anyhow::anyhow!("local engine {name} exited unexpectedly"))
133	                        }
134	                        Some(Ok((name, Err(error)))) => {
135	                            Err(error).with_context(|| format!("local engine {name} failed"))
136	                        }
137	                        Some(Err(error)) => {
138	                            Err(anyhow::anyhow!("local engine child task panicked: {error}"))
139	                        }
140	                        None => Err(anyhow::anyhow!("local engine child task set became empty")),
141	                    };
142	                }
143	                Some(step) = steps.recv() => {
144	                    if let Err(error) = self.dispatch_step(
145	                        step,
146	                        &anchor,
147	                        &mut streams,
148	                        &mut names,
149	                        &mut spec,
150	                        &output_tx,
151	                    ) {
152	                        break Err(error).context("failed to dispatch local engine step");
153	                    }
154	                }
155	                recv = input.recv() => {
156	                    let message = match recv.context("failed to receive local engine request") {
157	                        Ok(message) => message,
158	                        Err(error) => break Err(error),
159	                    };
160	                    if let Err(error) = self.handle_message(
161	                        message,
162	                        &mut streams,
163	                        &mut names,
164	                        &output_tx,
165	                    ) {
166	                        break Err(error).context("failed to handle local engine request");
167	                    }
168	                }
169	            }
170	        };
171	
172	        // Flip every in-flight request's abort flag so the scheduler retires
173	        // them on its next touch; dropping the partition handle afterwards
174	        // disconnects the submission channel and lets the driver drain out.
175	        for state in streams.values() {
176	            state.control.abort();
177	        }
178	        drop(output_tx);
179	        child_tasks.abort_all();
180	        while child_tasks.join_next().await.is_some() {}
181	
182	        run_result
183	    }
