315	    fn start_request(
316	        &self,
317	        request: EngineCoreRequest,
318	        streams: &mut HashMap<RequestId, SteppedStream>,
319	        names: &mut HashMap<String, RequestId>,
320	        output_tx: &tokio::sync::mpsc::UnboundedSender<
321	            vllm_engine_core_client::protocol::output::EngineCoreOutputs,
322	        >,
323	    ) -> Result<()> {
324	        let EngineCoreRequest {
325	            request_id,
326	            prompt_token_ids,
327	            sampling_params,
328	            ..
329	        } = request;
330	        let Some(prompt_tokens) = prompt_token_ids else {
331	            warn!("request {request_id} dropped: missing prompt_token_ids");
332	            return send_terminal_output(
333	                self.engine_index,
334	                output_tx,
335	                request_id,
336	                EngineCoreFinishReason::Error,
337	                None,
338	                None,
339	                None,
340	            );
341	        };
342	        let Some(sampling_params) = sampling_params else {
343	            warn!("request {request_id} dropped: missing sampling_params");
344	            return send_terminal_output(
345	                self.engine_index,
346	                output_tx,
347	                request_id,
348	                EngineCoreFinishReason::Error,
349	                None,
350	                None,
351	                None,
352	            );
353	        };
354	
355	        if let Some(unsupported) = crate::vllm::wire::unsupported_request_params(&sampling_params) {
356	            warn!("request {request_id} rejected: {unsupported}");
357	            return send_terminal_output(
358	                self.engine_index,
359	                output_tx,
360	                request_id,
361	                EngineCoreFinishReason::Error,
362	                None,
363	                None,
364	                None,
365	            );
366	        }
367	        let lora_adapter = match lora_adapter_from_sampling_params(&sampling_params) {
368	            Ok(adapter) => adapter,
369	            Err(error) => {
370	                let message = error.to_string();
371	                warn!("request {request_id} rejected: {message}");
372	                return send_terminal_output(
373	                    self.engine_index,
374	                    output_tx,
375	                    request_id,
376	                    EngineCoreFinishReason::Error,
377	                    Some(StopReason::Text(message)),
378	                    None,
379	                    None,
380	                );
381	            }
382	        };
383	        let kv_transfer_params = sampling_params
384	            .extra_args
385	            .as_ref()
386	            .and_then(|args| args.get("kv_transfer_params"))
387	            .cloned();
388	        let stop_sentinel_id = stop_sentinel_id(
389	            sampling_params.eos_token_id,
390	            &sampling_params.stop_token_ids,
391	        );
392	
393	        // Open the request's root span before submit so its context travels
394	        // into the scheduler as the parent of the queue/prefill/decode spans;
395	        // noop (no allocation, `from_span` yields `None`) when tracing is off.
396	        let trace_root = if crate::tracing_state::is_enabled() {
397	            Span::root("request", SpanContext::random())
398	                .with_property(|| ("request_id", request_id.clone()))
399	        } else {
400	            Span::noop()
401	        };
402	        let trace_parent = SpanContext::from_span(&trace_root);
403	        let control = self.scheduler.submit(Request {
404	            prompt_tokens,
405	            params: convert_sampling(&sampling_params),
406	            max_tokens: sampling_params.max_tokens as usize,
407	            lora_adapter,
408	            kv_transfer_params,
409	            logprobs: requested_logprobs(&sampling_params),
410	            prompt_logprobs: requested_prompt_logprobs(&sampling_params),
411	            trace_parent,
412	            client_label: Some(Arc::from(request_id.as_str())),
413	        });
414	
415	        names.insert(request_id.clone(), control.id());
416	        streams.insert(
417	            control.id(),
418	            SteppedStream::new(request_id, control, trace_root, stop_sentinel_id),
419	        );
420	        Ok(())
421	    }
422	}
