424	/// Per-request demux state, keyed by the contract's [`RequestId`]; `names`
425	/// maps the vLLM wire's string request id back to it for aborts.
426	struct SteppedStream {
427	    request_id: String,
428	    control: RequestControl,
429	    /// Queued/Scheduled wire events, held until the request's first shipped
430	    /// output (a scheduled-only update ships nothing on its own).
431	    first_token_events: Option<Vec<EngineCoreEvent>>,
432	    /// Set by `Scheduled`; a request refused or failed while still queued
433	    /// never prefilled and reports no prefill stats.
434	    prompt_tokens: Option<usize>,
435	    cached_tokens: usize,
436	    prefill_stats_sent: bool,
437	    /// P/D handoff metadata can arrive in an update with no token or
438	    /// terminal, so retain it until the next output carries it to the router.
439	    kv_transfer_params: Option<serde_json::Value>,
440	    /// The vLLM text decoder removes the final token from a stop-finished
441	    /// output. Keep an EOS or explicit stop token as that removable sentinel.
442	    stop_sentinel_id: Option<u32>,
443	    /// Request-lifetime root span; held only for its `Drop`, which closes the
444	    /// trace when the stream state is removed.
445	    #[allow(dead_code)]
446	    trace_root: Span,
447	}
448	
449	impl SteppedStream {
450	    fn new(
451	        request_id: String,
452	        control: RequestControl,
453	        trace_root: Span,
454	        stop_sentinel_id: Option<u32>,
455	    ) -> Self {
456	        Self {
457	            request_id,
458	            control,
459	            first_token_events: None,
460	            prompt_tokens: None,
461	            cached_tokens: 0,
462	            prefill_stats_sent: false,
463	            kv_transfer_params: None,
464	            stop_sentinel_id,
465	            trace_root,
466	        }
467	    }
468	
469	    fn fail_prompt(&mut self, error: &anyhow::Error) -> (Option<EngineCoreOutput>, bool) {
470	        warn!("request {} failed: {error:#}", self.request_id);
471	        self.control.abort();
472	        let output = engine_output(
473	            self.request_id.clone(),
474	            Vec::new(),
475	            None,
476	            Some(EngineCoreFinishReason::Error),
477	            Some(StopReason::Text(error.to_string())),
478	            self.first_token_events.take(),
479	            self.take_prefill_stats(),
480	        );
481	        (Some(output), true)
482	    }
483	
484	    /// Prefill stats for the request's first shipped output. Built lazily so
485	    /// a `cached_tokens` fact arriving after `Scheduled` (chunked prefill
486	    /// reports it with the first chunk) still lands in the stats. Upstream
487	    /// invariant: computed + cached == prompt. `None` for a request that
488	    /// never reached `Scheduled`.
489	    fn take_prefill_stats(&mut self) -> Option<PrefillStats> {
490	        if self.prefill_stats_sent {
491	            return None;
492	        }
493	        let prompt_tokens = self.prompt_tokens?;
494	        self.prefill_stats_sent = true;
495	        Some(PrefillStats {
496	            num_prompt_tokens: prompt_tokens as u32,
497	            num_computed_tokens: prompt_tokens.saturating_sub(self.cached_tokens) as u32,
498	            num_cached_tokens: self.cached_tokens as u32,
499	            num_local_cached_tokens: self.cached_tokens as u32,
500	            num_external_cached_tokens: 0,
501	            num_cache_creation_tokens: 0,
502	        })
503	    }
504	}
