506	/// Translate one request's step record into at most one wire output. A
507	/// record carrying only metadata (scheduled, cached, kv-transfer) ships
508	/// nothing; its facts wait in `state` for the first real output. Returns
509	/// `(output, terminated)`.
510	fn reduce_update(
511	    state: &mut SteppedStream,
512	    update: RequestUpdate,
513	    anchor: &UnixAnchor,
514	) -> (Option<EngineCoreOutput>, bool) {
515	    if let Some(scheduled) = update.scheduled {
516	        state.first_token_events = Some(vec![
517	            EngineCoreEvent {
518	                r#type: EngineCoreEventType::Queued,
519	                timestamp: anchor.unix(scheduled.queued_at),
520	            },
521	            EngineCoreEvent {
522	                r#type: EngineCoreEventType::Scheduled,
523	                timestamp: anchor.unix(scheduled.scheduled_at),
524	            },
525	        ]);
526	        state.prompt_tokens = Some(scheduled.prompt_tokens);
527	    }
528	    if let Some(cached) = update.cached_tokens {
529	        state.cached_tokens = cached;
530	    }
531	    if let Some(params) = update.kv_transfer {
532	        state.kv_transfer_params = Some(params);
533	    }
534	    let prompt_logprobs = match update.prompt_echo.map(to_wire_prompt_logprobs).transpose() {
535	        Ok(payload) => payload.flatten(),
536	        Err(error) => return state.fail_prompt(&error),
537	    };
538	
539	    let mut token_ids = update.tokens;
540	    let mut has_logprobs = false;
541	    let mut positions: Vec<PositionLogprobs> = Vec::with_capacity(token_ids.len());
542	    for (i, &id) in token_ids.iter().enumerate() {
543	        let logprob = update.logprobs.get(i).cloned().flatten();
544	        if let Some(position) = to_wire_position_logprobs(id, logprob) {
545	            has_logprobs = true;
546	            positions.push(position);
547	        } else {
548	            positions.push(PositionLogprobs {
549	                entries: Vec::new(),
550	            });
551	        }
552	    }
553	
554	    let mut finish_reason: Option<EngineCoreFinishReason> = None;
555	    let mut stop_reason: Option<StopReason> = None;
556	    let mut terminated = false;
557	    match update.terminal {
558	        None => {}
559	        Some(Terminal::Finished { reason, .. }) => {
560	            // PegaInfer suppresses EOS before emitting tokens, while vLLM's
561	            // text decoder expects the terminal Stop output to contain EOS
562	            // and unconditionally removes its final token.
563	            if reason == FinishReason::Stop
564	                && let Some(stop_sentinel_id) = state.stop_sentinel_id
565	            {
566	                token_ids.push(stop_sentinel_id);
567	                positions.push(PositionLogprobs {
568	                    entries: Vec::new(),
569	                });
570	            }
571	            finish_reason = Some(convert_finish_reason(reason));
572	            terminated = true;
573	        }
574	        Some(Terminal::Rejected { reason, .. }) => {
575	            // The vLLM wire only carries a string; typed classification stops
576	            // here and the rendered message is what reaches the client.
577	            let message = reason.to_string();
578	            warn!("request {} rejected: {message}", state.request_id);
579	            finish_reason = Some(EngineCoreFinishReason::Error);
580	            stop_reason = Some(StopReason::Text(message));
581	            terminated = true;
582	        }
583	        Some(Terminal::Failed { message, .. }) => {
584	            warn!("request {} failed: {message}", state.request_id);
585	            finish_reason = Some(EngineCoreFinishReason::Error);
586	            stop_reason = Some(StopReason::Text(message));
587	            terminated = true;
588	        }
589	    }
590	
591	    if token_ids.is_empty() && prompt_logprobs.is_none() && !terminated {
592	        return (None, false);
593	    }
594	
595	    let logprobs = has_logprobs.then_some(MaybeWireLogprobs::Direct(Logprobs { positions }));
596	    let mut output = engine_output(
597	        state.request_id.clone(),
598	        token_ids,
599	        logprobs,
600	        finish_reason,
601	        stop_reason,
602	        state.first_token_events.take(),
603	        state.take_prefill_stats(),
604	    );
605	    output.new_prompt_logprobs_tensors = prompt_logprobs;
606	    output.kv_transfer_params = state.kv_transfer_params.take();
607	    (Some(output), terminated)
608	}
