610	/// Renders the contract's monotonic timestamps as wall-clock floats for the
611	/// vLLM wire. One anchor per bridge: both readings taken together at startup,
612	/// so every rendered timestamp shares one clock base.
613	struct UnixAnchor {
614	    sys: f64,
615	    instant: Instant,
616	}
617	
618	impl UnixAnchor {
619	    fn now() -> Self {
620	        Self {
621	            sys: now_secs_f64(),
622	            instant: Instant::now(),
623	        }
624	    }
625	
626	    fn unix(&self, t: Instant) -> f64 {
627	        if t >= self.instant {
628	            self.sys + (t - self.instant).as_secs_f64()
629	        } else {
630	            self.sys - (self.instant - t).as_secs_f64()
631	        }
632	    }
633	}
